#include HEADER
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
#include <vector>
using Matrix=std::vector<std::vector<std::int64_t>>;
int main(int argc,char**argv){
 const int n=std::atoi(argv[1]),kind=std::atoi(argv[2]),path=std::atoi(argv[3]);
 const int reps=n<=16?3000:n<=64?100:n<=128?20:3;
 std::mt19937_64 rng(8983712);Matrix source(n,std::vector<std::int64_t>(n,INF));
 for(int i=0;i<n;++i){source[i][i]=0;for(int j=0;j<n;++j)if(i!=j){
  const auto w=std::int64_t(rng()%1000)+1;
  if(kind==0)source[i][j]=w;
  else if(kind==1){if(rng()%8==0)source[i][j]=w;}
  else if(kind==2)source[i][j]=w+std::int64_t(j-i)*100;
  else if(kind==3){if(j>i)source[i][j]=w-500;}
  else if(kind==4){if(i/8==j/8)source[i][j]=w;}
  else if(kind==5){if(j==i+1)source[i][j]=1;}
  else if(kind==6){source[i][j]=w;if(j==(i+1)%n)source[i][j]=-1;}
  else {const auto gap=INF/(std::int64_t(n)*2);source[i][j]=w+std::int64_t(j-i)*gap;}
 }}
 if(kind==4)for(int i=0;i+1<n;i+=16){source[i][i+1]=-3;source[i+1][i]=1;}
 std::int64_t ns=0;std::uint64_t checksum=0;std::vector<std::vector<int>> next;
 for(int rep=0;rep<reps;++rep){
  auto distance=source;if(path==2)next.clear();
  const auto start=std::chrono::steady_clock::now();
  const bool negative=path?FloydWarshall(distance,next):FloydWarshall(distance);
  ns+=std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now()-start).count();
  checksum+=negative;
  for(auto& row:distance)for(auto x:row)checksum=checksum*123731+std::uint64_t(x);
  if(path)for(auto& row:next)for(auto x:row)checksum=checksum*7927+std::uint64_t(x);
 }
 std::cout<<ns/reps<<' '<<checksum<<'\n';
}

