#include <random>
#include <string>
#include <vector>
int main(int argc,char**argv) {
    const int n=std::atoi(argv[1]); const std::string kind=argv[2];
    const bool thin = kind == "star" || kind == "isolated" || kind == "components" || kind == "star_in";
    const int reps=std::max(1,static_cast<int>(50000000LL/(std::int64_t(n)*n*(thin?16:n))));
    std::mt19937_64 rng(47131413);
    std::vector input(n,std::vector<std::int64_t>(n,INF));
    for(int i=0;i<n;++i){input[i][i]=0;for(int j=0;j<n;++j)if(i!=j){
        bool edge = kind == "dense" || kind == "zero" || kind == "nearINF" || kind == "nonfinite_range" || kind.rfind("hole",0)==0 || (kind == "sparse" && rng()%16==0);
        if(kind == "chain") edge = j == i+1;
        if(kind == "star") edge = i==0;
        if(kind == "star_in") edge = j==0;
        if(kind == "isolated") edge = false;
        if(kind == "components") edge = i/8 == j/8;
        if(edge)input[i][j]=kind=="zero"?0:kind=="nearINF"?(INF-1)/n:kind=="nonfinite_range"?(INF-1)/n+1:static_cast<std::int64_t>(rng()%1000);
    }}
    if (kind == "hole_early") input[0][1]=INF;
    if (kind == "hole_boundary") input[0][n-1]=INF;
    if (kind == "hole_middle") input[n/2][n/2+1]=INF;
    if (kind == "hole_late") input[n-1][n-2]=INF;
    double ns=0;std::uint64_t checksum=0;
    for(int r=0;r<reps;++r){auto distance=input;auto start=std::chrono::steady_clock::now();const bool negative=FloydWarshall(distance);auto stop=std::chrono::steady_clock::now();ns+=std::chrono::duration<double,std::nano>(stop-start).count();checksum+=negative;for(const auto&row:distance)for(auto x:row)checksum=checksum*16777619+std::uint64_t(x);}
    std::cout<<ns/reps<<' '<<checksum<<'\n';
}

