p=Path(__file__).parent;variants=['baseline','encoded_try_gcc'];rows=[];builds=[]
lock=open('/tmp/sirkit_performance_cpu4.lock','w');fcntl.flock(lock,fcntl.LOCK_EX)
for compiler in ['gcc']:
 for cfg in ['default','native']:
  for name in variants:
   cmd=['taskset','-c','4','/usr/bin/g++'if compiler=='gcc'else'clang++','-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS']
   if compiler=='clang':cmd+=['--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']
   if cfg=='native':cmd+=['-march=native']
   cmd += [f'-DHEADER="{p/(name+".hpp")}"',str(p/'try_bench.cpp'),'-o',str(p/f'try-boundary-{compiler}-{cfg}-{name}')]
   c=subprocess.run(cmd,capture_output=True,text=True);builds.append(dict(cmd=cmd,status=c.returncode,diagnostics=c.stderr));assert c.returncode==0,c.stderr
  dest=p/'run';dest.touch()
  for n in [63,64,65,100,128,256,512]:
   for kind in ['dense','zero','nearINF','nonfinite_range','hole_early','hole_boundary','hole_middle','hole_late']:
    for repeat in range(5):
     order=variants+['control'];random.Random(repeat+7453).shuffle(order)
     for name in order:
      src=p/f'try-boundary-{compiler}-{cfg}-{name if name!="control"else"baseline"}'
      with open(dest,'wb')as f:f.write(src.read_bytes())
      dest.chmod(0o755)
      q=subprocess.run(['taskset','-c','4',str(dest),str(n),kind],capture_output=True,text=True);assert q.returncode==0,q.stderr
      ns,checksum=q.stdout.split();rows.append(dict(compiler=compiler,cfg=cfg,n=n,kind=kind,variant=name,repeat=repeat,ns=float(ns),checksum=checksum))
    current=[x for x in rows if(x['compiler'],x['cfg'],x['n'],x['kind'])==(compiler,cfg,n,kind)];assert len({x['checksum']for x in current})==1
    vals={name:statistics.median(x['ns']for x in current if x['variant']==name)for name in variants+['control']}
    print(compiler,cfg,n,kind,{name:round(v/vals['baseline'],4)for name,v in vals.items()},flush=True)
    (p/'try-boundary-raw.json').write_text(json.dumps(dict(builds=builds,rows=rows),indent=2)+'\n')
