#include SIRKIT_FLOYD_TEST_SOURCE
#include SIRKIT_FLOYD_TEST_SOURCE
#include <array>
#include <cassert>
#include <iostream>
#include <random>
#include <stdexcept>
#include <string>
#include <vector>
#include <immintrin.h>
using Matrix = std::vector<std::vector<std::int64_t>>;
struct SaveMxcsr { unsigned saved = _mm_getcsr(); ~SaveMxcsr(){_mm_setcsr(saved);} };
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
Matrix reference(const Matrix& input){
 const int n=static_cast<int>(input.size());Matrix answer(n,std::vector<std::int64_t>(n,INF));
 for(int source=0;source<n;++source){auto&d=answer[source];d[source]=0;std::vector<bool> used(n);
  for(int step=0;step<n;++step){int u=-1;for(int v=0;v<n;++v)if(!used[v]&&(u==-1||d[v]<d[u]))u=v;
   if(u==-1||d[u]==INF)break;
   used[u]=true;
   for(int v=0;v<n;++v)if(input[u][v]!=INF)d[v]=std::min(d[v],d[u]+input[u][v]);
  }
 }
 return answer;
}
[[gnu::target("avx2")]] void min_compare(std::int64_t* dest,const std::int64_t*a,const std::int64_t*b){
 const auto x=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(a));
 const auto y=_mm256_loadu_si256(reinterpret_cast<const __m256i*>(b));
 _mm256_storeu_si256(reinterpret_cast<__m256i*>(dest),_mm256_castpd_si256(_mm256_min_pd(_mm256_castsi256_pd(x),_mm256_castsi256_pd(y))));
}
std::size_t rollback_checks() {
 SaveMxcsr save;
 _mm_setcsr((save.saved | 0x1f80U) & ~(0x6000U | 0x8040U | 0x3fU));
 std::size_t checks = 0;
 for (int n : {64,65,66,67,100,127,128,129,255,256,257}) {
  const std::array rows = {0,1,n/2,n-1};
  const std::array columns = {0,1,2,3,4,5,6,7,n-4,n-3,n-2,n-1};
  for (int row : rows) for (int column : columns) {
   if (row == column) continue;
   Matrix input(n,std::vector<std::int64_t>(n,1));
   for (int i=0;i<n;++i) input[i][i]=0;
   auto expected=input;
   input[row][column]=INF;
   // 一辺だけ欠けた単位重み完全有向グラフでは、その一組だけ距離2。
   expected[row][column]=2;
   const auto before=_mm_getcsr();
   require(!FloydWarshall(input), "rollback negative flag mismatch");
   require(input == expected, "partial rollback boundary mismatch");
   require(_mm_getcsr()==before, "rollback changed MXCSR flags/control");
   ++checks;
  }
 }
 return checks;
}
int main(){
 try{
  require(__builtin_cpu_supports("avx2"),"AVX2 unavailable for local encoding proof");
  constexpr std::int64_t bias=INT64_C(0x3ff0000000000000);
  const std::array<std::int64_t,16> values={0,1,2,3,127,128,255,256,INT64_C(0xffffffff),INF/2,INF-2,INF-1,INF,INF+1,2*INF-1,2*INF};
  std::vector<std::pair<Matrix,Matrix>> graphs;std::mt19937_64 rng(78131246);
  for(int n:{0,1,7,8,31,32,63,64,65,100,127,128,129,255,256,257})for(int kind=0;kind<11;++kind){
   Matrix input(n,std::vector<std::int64_t>(n,INF));for(int i=0;i<n;++i){input[i][i]=kind%2?INF:0;for(int j=0;j<n;++j)if(i!=j){
    bool edge=kind==0||rng()%8==0;
    if(kind==2)edge=edge&&((i<n/2)==(j<n/2));
    if(kind==3)edge=j==i+1;
    if(kind==5)edge=i==0;
    if(kind==6)edge=j==0;
    if(kind==7)edge=false;
    if(kind>=8)edge=true;
    if(edge)input[i][j]=kind==3||kind==8?(INF-1)/n:kind==9?(INF-1)/n+1:kind==4||kind==10?0:static_cast<std::int64_t>(rng()%1024);
   }}
   graphs.emplace_back(input,reference(input));
  }
  std::size_t min_checks=0,graph_checks=0;
  SaveMxcsr save;
  for(unsigned round=0;round<4;++round)for(unsigned daz=0;daz<2;++daz)for(unsigned ftz=0;ftz<2;++ftz){
   const unsigned mode=(save.saved|0x1f80U)&~(0x6000U|0x8040U|0x3fU);
   const unsigned control=mode|(round<<13)|(daz<<6)|(ftz<<15);
   for(unsigned masks:{0U,0x1f80U}){
    _mm_setcsr((control&~0x1f80U)|masks);
    for(auto a:values)for(auto b:values){
     std::int64_t aa[4]={bias+a,bias+a,bias+b,bias+b};std::int64_t bb[4]={bias+b,bias+a,bias+a,bias+b};std::int64_t result[4];
     const auto before=_mm_getcsr();min_compare(result,aa,bb);require(_mm_getcsr()==before,"minpd changed MXCSR flags/control");
     require(result[0]==bias+std::min(a,b)&&result[1]==bias+a&&result[2]==bias+std::min(a,b)&&result[3]==bias+b,"encoded min mismatch");++min_checks;
    }
   }
   _mm_setcsr(control);
   for(const auto&[input,expected]:graphs){auto actual=input;const auto before=_mm_getcsr();require(!FloydWarshall(actual),"unexpected negative cycle");require(actual==expected,"Dijkstra mismatch");require(_mm_getcsr()==before,"Floyd changed MXCSR flags/control");++graph_checks;}
  }
  _mm_setcsr(save.saved);
  const auto rollback = rollback_checks();
  std::cout<<rollback<<" partial rollback cases; "<<min_checks<<" encoded min/MXCSR cases; "<<graph_checks<<" independent Dijkstra/MXCSR graph cases passed\n";
 }catch(const std::exception&ex){std::cerr<<ex.what()<<'\n';return 1;}
}

